     static void convert_To_Len_th_base(int n, int arr[],  
                                        int len, int L) 
     { 
         String hold = "";
         // Sequence is of length L 
         for (int i = 0; i < L; i++)  
         { 
             // Print the ith element 
             // of sequence 
             hold += arr[n % len] +"";
             n /= len; 
